					type: "Literal",
					phase: 2,
				},
				{
					type: "VariableDeclarator",
					phase: 2,
				},
				{
					type: "VariableDeclaration",
					phase: 2,
				},
				{
					type: "Program",
					phase: 2,
				},
			]);
