			// Group steps by target node
			const nodeSteps = new Map();
			visitSteps.forEach(step => {
				const key = step.target.type;
				if (!nodeSteps.has(key)) {
					nodeSteps.set(key, []);
				}
				nodeSteps.get(key).push(step.phase);
