	describe("traverse()", () => {
		it("should return an array of steps", () => {
			const code = "var foo = 1;";
			const ast = espree.parse(code, DEFAULT_CONFIG);
			const sourceCode = new SourceCode(code, ast);
			const steps = sourceCode.traverse();

