						rules: {
							checker: {
								create(context) {
									const sourceCode = context.sourceCode;

									spy = sinon.spy(functionDecl => {
										const blockStatement =
											functionDecl.body;

										// Function parameter references
										const paramRef =
											blockStatement.body[0].expression;
										const NaNRef =
											blockStatement.body[1].expression;

										assert.strictEqual(
											paramRef.name,
