			"/(?<zero>0)/": "/(?<zero>0)/",
			"/(?<zero>0)/s": "/(?<zero>0)/s",
			"/(?<=a)b/s": "/(?<=a)b/s",

			// simple template literals
			"``": "",
			"`foo`": "foo",

			// unsupported
			"`${''}`": null,
			"`${0}`": null,
			"tag``": null,
			"-0": null,
			"-1": null,
			"1 + 2": null,
			"[]": null,
			"({})": null,
			foo: null,
			undefined: null,
			this: null,
			"(function () {})": null,
		};

		Object.keys(expectedResults).forEach(key => {
			it(`should return ${expectedResults[key]} for ${key}`, () => {
				const ast = espree.parse(key, { ecmaVersion: 2018 });

